Example:
{'user': {'name': 'Ali', 'settings': {'theme': 'dark'}}, 'active': True}
becomes
{'user.name': 'Ali', 'user.settings.theme': 'dark', 'active': True}

response.text:
def flatten_dict(data, prefix=''):
    flat = {}
    for key, value in data.items():
        new_key = f"{prefix}.{key}" if prefix else key
        if isinstance(value, dict):
            flat.update(flatten_dict(value, new_key))
        else:
            flat[new_key] = value
    return flat
